#!/usr/bin/env bash
# One-time (idempotent) project bootstrap.
#
# The android/ and ios/ platform folders are generated by the Flutter tool, not hand-written, so they are not
# stored in this repository until you run this script and commit the result. It:
#   1. runs `flutter create` to generate android/ and ios/ (existing Dart code is never overwritten),
#   2. removes the sample test that `flutter create` adds (it references a MyApp that does not exist here),
#   3. patches the platform files (storage permissions, file sharing, app name) via tool/patch_platforms.py.
#
# Usage:  tool/bootstrap.sh [--signing]
#   --signing   also wire Android release signing to android/key.properties (see docs/RELEASING.md)
set -euo pipefail
cd "$(dirname "$0")/.."

if ! command -v flutter >/dev/null 2>&1; then
  echo "error: flutter is not on PATH. Install Flutter (stable, >= 3.22) first: https://docs.flutter.dev/get-started/install" >&2
  exit 1
fi

ORG="${PF_ORG:-com.promptforge}"
flutter create --platforms=android,ios --org "$ORG" --project-name prompt_forge .
rm -f test/widget_test.dart

python3 tool/patch_platforms.py "$@"
python3 tool/make_icons.py || echo "(launcher icons skipped - run: pip install pillow && python3 tool/make_icons.py)"
flutter pub get
echo
echo "Bootstrap complete. Next: flutter analyze && flutter test && flutter run"
